const input = $input.first().json;
const payload = input.body ?? input;

const allowedStatuses = ['triage', 'toDo', 'progress', 'feedback', 'done'];
const statusLabels = {
  triage: 'Triage',
  toDo: 'To do',
  progress: 'In progress',
  feedback: 'Await feedback',
  done: 'Done',
};

const oldStatus = String(payload.oldStatus || '').trim();
const newStatus = String(payload.newStatus || '').trim();
const creatorEmail = String(payload.creatorEmail || '').trim().toLowerCase();
const creatorType = String(payload.creatorType || 'internal').trim().toLowerCase();

// Exakte Prüfung auf gültige E-Mail (kein leerer String erlaubt!)
const validEmail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(creatorEmail);
const validStatus = allowedStatuses.includes(newStatus);

// NUR benachrichtigen wenn:
// 1. Es ein externer Request ist (creatorType === 'external')
// 2. Eine gültige E-Mail existiert (nicht leer!)
// 3. Sich der Status wirklich geändert hat
const shouldNotify = (creatorType === 'external') && validEmail && validStatus && (oldStatus !== newStatus);

return [{
  json: {
    taskId: String(payload.taskId || ''),
    title: String(payload.title || 'Join-Ticket').trim().slice(0, 120),
    oldStatus,
    newStatus,
    newStatusLabel: statusLabels[newStatus] || newStatus,
    creatorName: String(payload.creatorName || 'Stakeholder').trim(),
    creatorEmail,
    creatorType,
    shouldNotify
  },
}];
